<template>
  <div class="docnet-agents-page q-gutter-y-md">
    <div class="page-header">
      <h2 class="page-title">{{ $t('docnet_agents_page_title') }}</h2>
      <p class="page-subtitle text-grey-7">
        {{ $t('docnet_agents_page_subtitle') }}
      </p>
    </div>

    <!-- Category routing: friendly "problem category → agent" mapping.
         No codes shown; internally each row is a code_prefix → agent route. -->
    <q-card flat bordered class="routes-card" data-test="routes-card">
      <q-card-section class="row items-center q-pa-md">
        <q-icon name="alt_route" size="22px" color="primary" class="q-mr-md" />
        <div>
          <div class="section-title">{{ $t('docnet_routes_title') }}</div>
          <div class="section-subtitle text-grey-7">
            {{ $t('docnet_routing_intro') }}
          </div>
        </div>
      </q-card-section>

      <q-separator />

      <q-card-section
        v-if="loadingRoutes || loadingAgents"
        class="q-pa-md text-center"
      >
        <q-spinner color="primary" size="24px" />
      </q-card-section>

      <q-list v-else separator>
        <q-item
          v-for="cat in categories"
          :key="cat.prefix"
          class="category-row"
          :data-test="`category-${cat.prefix}`"
        >
          <q-item-section>
            <q-item-label class="category-label">{{ cat.label }}</q-item-label>
          </q-item-section>
          <q-item-section side class="category-agent">
            <q-select
              outlined
              dense
              emit-value
              map-options
              :model-value="currentAgentForCategory(cat.prefix)"
              :options="agentSelectOptions"
              :loading="savingPrefix === cat.prefix"
              :disable="savingPrefix !== null"
              :data-test="`category-agent-${cat.prefix}`"
              @update:model-value="(v) => onCategoryAgentChange(cat.prefix, v)"
            />
          </q-item-section>
        </q-item>
      </q-list>
    </q-card>

    <!-- Advanced: expert code-level routing + any non-category routes.
         Hidden by default so the simple category view stays clean. -->
    <q-expansion-item
      icon="tune"
      :label="$t('docnet_advanced')"
      class="advanced-card"
      data-test="advanced-routing"
    >
      <q-card flat bordered>
        <q-card-section class="row items-center q-pa-md">
          <div class="section-subtitle text-grey-7 col">
            {{ $t('docnet_advanced_hint') }}
          </div>
          <q-btn
            unelevated
            no-caps
            size="sm"
            color="primary"
            icon="add"
            :label="$t('docnet_add_custom_route')"
            data-test="add-route"
            @click="openAddDialog"
          />
        </q-card-section>
        <q-separator />
        <q-list v-if="customRoutes.length" separator>
          <q-item
            v-for="row in customRoutes"
            :key="row.id"
            :data-test="`custom-route-${row.id}`"
          >
            <q-item-section>
              <q-item-label>
                <code class="prefix-code">{{ row.code_prefix }}</code>
              </q-item-label>
              <q-item-label caption>
                {{ agentLabel(row.agent_key) }}
                <q-icon
                  v-if="!agentByKey[row.agent_key]"
                  name="warning"
                  color="amber-7"
                  size="14px"
                  :title="$t('docnet_agent_unknown_warn')"
                />
              </q-item-label>
            </q-item-section>
            <q-item-section side>
              <div class="row items-center no-wrap">
                <q-toggle
                  :model-value="row.enabled"
                  color="primary"
                  dense
                  :data-test="`route-enabled-${row.id}`"
                  @update:model-value="(v: boolean) => onToggleEnabled(row, v)"
                />
                <q-btn
                  flat
                  dense
                  round
                  size="sm"
                  icon="delete"
                  color="negative"
                  :title="$t('delete')"
                  :data-test="`route-delete-${row.id}`"
                  @click="onDelete(row)"
                />
              </div>
            </q-item-section>
          </q-item>
        </q-list>
        <q-card-section v-else class="text-grey-7 q-pa-md">
          {{ $t('docnet_advanced_empty') }}
        </q-card-section>
      </q-card>
    </q-expansion-item>

    <!-- Agents registry: read-only -->
    <q-card flat bordered class="agents-card" data-test="agents-card">
      <q-card-section class="row items-center q-pa-md">
        <q-icon name="smart_toy" size="22px" color="primary" class="q-mr-md" />
        <div>
          <div class="section-title">{{ $t('docnet_agents_title') }}</div>
          <div class="section-subtitle text-grey-7">
            {{ $t('docnet_agents_subtitle') }}
          </div>
        </div>
      </q-card-section>

      <q-separator />

      <q-card-section
        v-if="loadingAgents"
        class="q-pa-md text-center text-grey-7"
      >
        <q-spinner color="primary" size="24px" />
      </q-card-section>

      <q-card-section v-else class="agents-grid q-pa-md">
        <div
          v-for="agent in agents"
          :key="agent.agent_key"
          class="agent-card"
          :data-test="`agent-card-${agent.agent_key}`"
        >
          <div class="agent-card-header">
            <q-chip
              dense
              square
              color="primary"
              text-color="white"
              class="agent-key-chip"
            >
              {{ humanizeAgentKey(agent.agent_key) }}
            </q-chip>
            <span class="agent-label">
              {{ agentDisplayLabel(agent.agent_key) }}
            </span>
          </div>
          <div class="agent-description">
            {{ agentDisplayDescription(agent.agent_key) }}
          </div>
          <div class="agent-meta">
            <div class="meta-row">
              <span class="meta-label">{{ $t('docnet_celery_task') }}:</span>
              <code>{{ agent.celery_task }}</code>
            </div>
            <div class="meta-row">
              <span class="meta-label">{{ $t('docnet_default_prefixes') }}:</span>
              <q-chip
                v-for="prefix in agent.default_code_prefixes"
                :key="prefix"
                dense
                square
                color="grey-3"
                text-color="grey-9"
                class="prefix-chip"
              >
                <code>{{ prefix }}</code>
              </q-chip>
            </div>
          </div>
        </div>
      </q-card-section>
    </q-card>

    <!-- Add / Edit dialog -->
    <q-dialog v-model="dialogOpen" no-backdrop-dismiss>
      <q-card class="route-dialog" data-test="route-dialog">
        <q-card-section>
          <div class="text-h6">
            {{ editingRoute ? $t('docnet_edit_route') : $t('docnet_add_route') }}
          </div>
        </q-card-section>
        <q-separator />
        <q-card-section class="q-gutter-y-md">
          <!-- Edit mode: the prefix is the route key — read-only. -->
          <q-input
            v-if="editingRoute"
            outlined
            dense
            v-model="dialogForm.code_prefix"
            :label="$t('docnet_route_target')"
            readonly
            data-test="dialog-code-prefix"
          />

          <!-- Add mode: pick a rule family or a specific rule from the
               validation-rules catalog. Produces the code_prefix the
               backend stores. Expert toggle reveals raw free-text. -->
          <template v-else>
            <q-select
              v-if="!expertPrefix"
              outlined
              dense
              clearable
              use-input
              input-debounce="200"
              v-model="selectedFinding"
              :options="findingOptionsFiltered"
              option-label="label"
              :label="$t('docnet_route_target')"
              :hint="$t('docnet_route_target_hint')"
              data-test="dialog-target"
              @filter="filterFindings"
              @update:model-value="onFindingSelected"
            >
              <template #option="scope">
                <q-item v-bind="scope.itemProps">
                  <q-item-section>
                    <q-item-label>{{ scope.opt.label }}</q-item-label>
                    <q-item-label caption class="prefix-code">
                      {{ scope.opt.caption }}
                    </q-item-label>
                  </q-item-section>
                  <q-item-section side>
                    <q-badge
                      :color="
                        scope.opt.kind === 'family' ? 'primary' : 'grey-5'
                      "
                      :label="
                        scope.opt.kind === 'family'
                          ? $t('docnet_route_kind_family')
                          : $t('docnet_route_kind_rule')
                      "
                    />
                  </q-item-section>
                </q-item>
              </template>
              <template #no-option>
                <q-item>
                  <q-item-section class="text-grey-7">
                    {{ $t('docnet_route_no_findings') }}
                  </q-item-section>
                </q-item>
              </template>
            </q-select>

            <q-input
              v-else
              outlined
              dense
              v-model="dialogForm.code_prefix"
              :label="$t('docnet_route_code_prefix')"
              :hint="$t('docnet_route_code_prefix_hint')"
              data-test="dialog-code-prefix"
            />

            <q-toggle
              v-model="expertPrefix"
              dense
              size="sm"
              :label="$t('docnet_route_expert_toggle')"
              data-test="dialog-expert-toggle"
              @update:model-value="onExpertToggle"
            />
          </template>

          <q-select
            outlined
            dense
            v-model="dialogForm.agent_key"
            :options="agentOptions"
            :label="$t('docnet_route_agent_key')"
            emit-value
            map-options
            data-test="dialog-agent-key"
          />
          <q-toggle
            v-model="dialogForm.enabled"
            :label="$t('docnet_route_enabled')"
            data-test="dialog-enabled"
          />
        </q-card-section>
        <q-separator />
        <q-card-actions align="right" class="q-pa-md">
          <q-btn
            flat
            no-caps
            :label="$t('cancel')"
            data-test="dialog-cancel"
            @click="dialogOpen = false"
          />
          <q-btn
            unelevated
            no-caps
            color="primary"
            :label="$t('save')"
            :loading="dialogSaving"
            :disable="!dialogForm.code_prefix || !dialogForm.agent_key"
            data-test="dialog-save"
            @click="onDialogSave"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useQuasar } from 'quasar';
import { notify } from 'src/components/notifications/notify';
import { ApiExceptions } from 'src/exceptions/index';
import {
  notificationRoutingApiService,
  validationRulesApiService,
} from 'src/services';
import type {
  AgentRegistryEntry,
  NotificationRoute,
} from 'src/services/settings/NotificationRoutingApiService';
import type { ValidationRuleRow } from 'src/services/settings/ValidationRulesApiService';

interface DialogForm {
  code_prefix: string;
  agent_key: string;
  enabled: boolean;
}

/** One entry in the "Apply to which findings?" picker. `value` is the
 *  string written to the route's code_prefix (a family prefix like
 *  "VAL-IBAN-", an exact rule code, or "*"). */
interface FindingOption {
  label: string;
  value: string;
  caption: string;
  kind: 'family' | 'rule';
}

export default defineComponent({
  name: 'DocNetAgentsList',
  setup() {
    // useQuasar() exposes $q (incl. the Dialog plugin) to the Options
    // API blocks below — used for the styled delete-confirm dialog.
    return { $q: useQuasar() };
  },
  data() {
    return {
      loadingAgents: false,
      loadingRoutes: false,
      agents: [] as AgentRegistryEntry[],
      routes: [] as NotificationRoute[],
      // Validation-rules catalog — powers the Add-route picker.
      rules: [] as ValidationRuleRow[],
      dialogOpen: false,
      dialogSaving: false,
      editingRoute: null as NotificationRoute | null,
      dialogForm: {
        code_prefix: '',
        agent_key: '',
        enabled: true,
      } as DialogForm,
      // Add-route picker state (advanced / expert routing).
      selectedFinding: null as FindingOption | null,
      findingOptionsFiltered: [] as FindingOption[],
      expertPrefix: false,
      // Per-category save indicator for the category-routing list.
      savingPrefix: null as string | null,
    };
  },
  computed: {
    agentByKey(): Record<string, AgentRegistryEntry> {
      const out: Record<string, AgentRegistryEntry> = {};
      for (const a of this.agents) out[a.agent_key] = a;
      return out;
    },
    agentOptions() {
      return this.agents.map((a) => ({
        label: `${a.label} (${a.agent_key})`,
        value: a.agent_key,
      }));
    },
    /** Friendly problem categories the customer routes — derived from
     *  the agents' shipped default_code_prefixes (the meaningful
     *  families) plus a catch-all. Each maps to an internal code_prefix;
     *  no code is shown to the user. */
    categories(): { prefix: string; label: string }[] {
      const fams = new Set<string>();
      for (const a of this.agents) {
        for (const p of a.default_code_prefixes) {
          if (p && p !== '*') fams.add(p);
        }
      }
      const list = [...fams]
        .sort()
        .map((p) => ({ prefix: p, label: this.familyLabel(p) }));
      list.push({
        prefix: '*',
        label: this.$t('docnet_route_catch_all_category'),
      });
      return list;
    },
    /** code_prefix → route lookup for the current per-category state. */
    routeByPrefix(): Record<string, NotificationRoute> {
      const m: Record<string, NotificationRoute> = {};
      for (const r of this.routes) m[r.code_prefix] = r;
      return m;
    },
    /** Agent dropdown options for a category row: "Standard" (fall back
     *  to the default agent) + every available agent. */
    agentSelectOptions(): { label: string; value: string }[] {
      return [
        { label: this.$t('docnet_route_standard'), value: '' },
        ...this.agents.map((a) => ({
          label: this.agentDisplayLabel(a.agent_key),
          value: a.agent_key,
        })),
      ];
    },
    /** Routes that don't correspond to a known category (e.g. exact
     *  rule codes added via the expert picker) — surfaced read/manage
     *  under "Advanced" so nothing is orphaned. */
    customRoutes(): NotificationRoute[] {
      const known = new Set(this.categories.map((c) => c.prefix));
      return this.routes.filter((r) => !known.has(r.code_prefix));
    },
    /** Options for the Add-route "Apply to which findings?" picker:
     *  rule families (the agent-shipped prefixes) + a catch-all + every
     *  individual catalog rule. Selecting one fills code_prefix. */
    findingOptions(): FindingOption[] {
      const opts: FindingOption[] = [];

      // Families = the meaningful prefixes the agents ship with (same
      // set "Suggest defaults" uses), excluding the catch-all.
      const families = new Set<string>();
      for (const a of this.agents) {
        for (const p of a.default_code_prefixes) {
          if (p && p !== '*') families.add(p);
        }
      }
      for (const prefix of [...families].sort()) {
        const n = this.rules.filter((r) => r.code.startsWith(prefix)).length;
        opts.push({
          value: prefix,
          label: this.familyLabel(prefix),
          caption: n
            ? `${prefix} · ${n} ${this.$t('docnet_route_rules_word')}`
            : prefix,
          kind: 'family',
        });
      }

      // Catch-all.
      opts.push({
        value: '*',
        label: this.$t('docnet_route_catch_all'),
        caption: '*',
        kind: 'family',
      });

      // Specific rules from the catalog.
      for (const r of this.rules) {
        opts.push({
          value: r.code,
          label: r.field_label || r.description || r.code,
          caption: r.code,
          kind: 'rule',
        });
      }
      return opts;
    },
  },
  mounted() {
    this.loadAll();
  },
  methods: {
    agentLabel(key: string): string {
      return this.agentDisplayLabel(key);
    },
    /** Translatable agent display name. Uses the Tolgee key
     *  `docnet_agent_<key>_label` when present, else falls back to the
     *  backend-provided label (for agents shipped without a key yet). */
    agentDisplayLabel(key: string): string {
      const tk = `docnet_agent_${key}_label`;
      const t = this.$t(tk);
      return t && t !== tk ? t : this.agentByKey[key]?.label || key;
    },
    /** Translatable agent description, same fallback rule as the label. */
    agentDisplayDescription(key: string): string {
      const tk = `docnet_agent_${key}_desc`;
      const t = this.$t(tk);
      return t && t !== tk ? t : this.agentByKey[key]?.description || '';
    },
    /** Readable form of a raw agent_key for the registry chip, e.g.
     *  "banking_bot" → "Banking Bot". Keeps the chip human instead of
     *  showing the snake_case identifier. */
    humanizeAgentKey(key: string): string {
      return (key || '')
        .split('_')
        .filter(Boolean)
        .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
        .join(' ');
    },
    async loadAll() {
      this.loadingAgents = true;
      this.loadingRoutes = true;
      try {
        const [agentsResp, routesResp] = await Promise.all([
          notificationRoutingApiService.listAgents(),
          notificationRoutingApiService.listRoutes(),
        ]);
        this.agents = agentsResp?.agents || [];
        this.routes = routesResp?.routes || [];
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as any));
      } finally {
        this.loadingAgents = false;
        this.loadingRoutes = false;
      }
      // Rules catalog is best-effort: if it fails the picker simply
      // shows families + catch-all (+ expert free-text) without the
      // per-rule entries — routing management still works.
      try {
        const rulesResp = await validationRulesApiService.list();
        this.rules = rulesResp?.data || [];
      } catch {
        this.rules = [];
      }
    },
    openAddDialog() {
      this.editingRoute = null;
      this.dialogForm = {
        code_prefix: '',
        agent_key: this.agents[0]?.agent_key || '',
        enabled: true,
      };
      this.selectedFinding = null;
      this.expertPrefix = false;
      this.findingOptionsFiltered = this.findingOptions;
      this.dialogOpen = true;
    },
    openEditDialog(row: NotificationRoute) {
      this.editingRoute = row;
      this.dialogForm = {
        code_prefix: row.code_prefix,
        agent_key: row.agent_key,
        enabled: row.enabled,
      };
      this.dialogOpen = true;
    },
    /** Current agent for a category row, or '' (= "Standard"/no route). */
    currentAgentForCategory(prefix: string): string {
      return this.routeByPrefix[prefix]?.agent_key || '';
    },
    /** Assign (or clear) the agent for a problem category. Empty value
     *  means "Standard" → remove the route so the finding falls back to
     *  the default agent. */
    async onCategoryAgentChange(prefix: string, agentKey: string) {
      this.savingPrefix = prefix;
      try {
        if (!agentKey) {
          if (this.routeByPrefix[prefix]) {
            await notificationRoutingApiService.deleteRoute(prefix);
          }
        } else {
          await notificationRoutingApiService.upsertRoute(
            prefix,
            agentKey,
            true,
          );
        }
        notify.success(this.$t('docnet_route_saved'));
        await this.loadAll();
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as any));
      } finally {
        this.savingPrefix = null;
      }
    },
    /** Friendly name for a known rule-family prefix; falls back to the
     *  raw prefix for families without a curated label. */
    familyLabel(prefix: string): string {
      const map: Record<string, string> = {
        'VAL-IBAN-': this.$t('docnet_family_iban'),
        'VAL-VAT-': this.$t('docnet_family_vat'),
        'BR-DE-': this.$t('docnet_family_br_de'),
        'BR-CO-': this.$t('docnet_family_br_co'),
      };
      return map[prefix] || prefix;
    },
    /** q-select `use-input` handler — case-insensitive filter over the
     *  option label + caption. */
    filterFindings(val: string, update: (cb: () => void) => void) {
      update(() => {
        const needle = (val || '').toLowerCase();
        this.findingOptionsFiltered = needle
          ? this.findingOptions.filter(
              (o) =>
                o.label.toLowerCase().includes(needle) ||
                o.caption.toLowerCase().includes(needle),
            )
          : this.findingOptions;
      });
    },
    onFindingSelected(opt: FindingOption | null) {
      this.dialogForm.code_prefix = opt?.value || '';
    },
    /** When leaving expert mode, try to re-bind the current free-text
     *  prefix to a matching picker option so the two stay in sync. */
    onExpertToggle(expert: boolean) {
      if (!expert) {
        const current = this.dialogForm.code_prefix;
        this.selectedFinding =
          this.findingOptions.find((o) => o.value === current) || null;
        this.findingOptionsFiltered = this.findingOptions;
      }
    },
    async onDialogSave() {
      this.dialogSaving = true;
      try {
        await notificationRoutingApiService.upsertRoute(
          this.dialogForm.code_prefix.trim(),
          this.dialogForm.agent_key,
          this.dialogForm.enabled,
        );
        notify.success(this.$t('docnet_route_saved'));
        this.dialogOpen = false;
        await this.loadAll();
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as any));
      } finally {
        this.dialogSaving = false;
      }
    },
    async onToggleEnabled(row: NotificationRoute, value: boolean) {
      const prev = row.enabled;
      row.enabled = value;
      try {
        await notificationRoutingApiService.upsertRoute(
          row.code_prefix,
          row.agent_key,
          value,
        );
      } catch (err) {
        row.enabled = prev;
        notify.error(ApiExceptions.getErrorMessage(err as any));
      }
    },
    onDelete(row: NotificationRoute) {
      this.$q
        .dialog({
          title: this.$t('confirm'),
          message: this.$t('docnet_route_delete_confirm', {
            prefix: row.code_prefix,
          }),
          persistent: true,
          ok: {
            label: this.$t('delete'),
            color: 'negative',
            unelevated: true,
            noCaps: true,
          },
          cancel: {
            label: this.$t('cancel'),
            flat: true,
            noCaps: true,
          },
        })
        .onOk(async () => {
          try {
            await notificationRoutingApiService.deleteRoute(row.code_prefix);
            notify.success(this.$t('docnet_route_deleted'));
            this.routes = this.routes.filter((r) => r.id !== row.id);
          } catch (err) {
            notify.error(ApiExceptions.getErrorMessage(err as any));
          }
        });
    },
  },
});
</script>

